(()=>{const modal=document.getElementById('speaker-photo-dialog');if(!modal)return;const image=document.getElementById('speaker-photo-full'),caption=document.getElementById('speaker-photo-caption'),original=document.getElementById('speaker-photo-original');let trigger;document.querySelectorAll('[data-speaker-photo]').forEach(button=>button.addEventListener('click',()=>{trigger=button;image.src=button.dataset.speakerPhoto;image.alt=button.dataset.caption;caption.textContent=button.dataset.caption;if(original)original.href=button.dataset.speakerPhoto;modal.showModal()}));modal.querySelector('button').addEventListener('click',()=>modal.close());modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modal.close()}});modal.addEventListener('close',()=>trigger?.focus())})();
